#!/usr/bin/env python3
import argparse
import json
from pathlib import Path

SEVERITY_ORDER = {"critical": 4, "high": 3, "medium": 2, "low": 1, "info": 0}

def load_json(path: Path):
    with path.open("r", encoding="utf-8") as handle:
        return json.load(handle)

def validate_scope(scope):
    required = {"engagement", "targets", "excluded_targets", "test_window"}
    missing = required - scope.keys()
    if missing:
        raise ValueError(f"Missing scope fields: {sorted(missing)}")
    if not scope["targets"]:
        raise ValueError("At least one target is required")

def validate_finding(finding):
    required = {"id", "title", "severity", "confidence", "asset", "status", "evidence", "impact", "remediation", "retest"}
    missing = required - finding.keys()
    if missing:
        raise ValueError(f"Finding {finding.get('id', '?')} missing: {sorted(missing)}")
    if finding["severity"] not in SEVERITY_ORDER:
        raise ValueError(f"Unsupported severity: {finding['severity']}")
    if finding["confidence"] not in {"high", "medium", "low"}:
        raise ValueError(f"Unsupported confidence: {finding['confidence']}")

def render_report(scope, findings):
    for finding in findings:
        validate_finding(finding)
    findings = sorted(findings, key=lambda item: SEVERITY_ORDER[item["severity"]], reverse=True)
    lines = [
        f"# Security Assessment Report — {scope['engagement']}",
        "",
        "## Scope",
        f"Targets: {', '.join(scope['targets'])}",
        f"Excluded: {', '.join(scope['excluded_targets']) or 'None stated'}",
        f"Test window: {scope['test_window']}",
        "",
        "## Findings",
    ]
    for finding in findings:
        lines.extend([
            f"### {finding['id']} — {finding['title']}",
            f"- Severity: {finding['severity']}",
            f"- Confidence: {finding['confidence']}",
            f"- Asset: {finding['asset']}",
            f"- Status: {finding['status']}",
            f"- Evidence: {finding['evidence']}",
            f"- Impact: {finding['impact']}",
            f"- Remediation: {finding['remediation']}",
            f"- Retest: {finding['retest']}",
            "",
        ])
    return "\n".join(lines)

def main():
    parser = argparse.ArgumentParser(description="Generate a report from local fictional assessment data")
    parser.add_argument("scope", type=Path)
    parser.add_argument("findings", type=Path)
    parser.add_argument("--output", type=Path, default=Path("report.md"))
    args = parser.parse_args()

    scope = load_json(args.scope)
    findings = load_json(args.findings)
    if not isinstance(findings, list):
        raise ValueError("findings.json must contain a JSON array")
    validate_scope(scope)
    report = render_report(scope, findings)
    args.output.write_text(report + "\n", encoding="utf-8")
    print(f"Wrote {args.output}")

if __name__ == "__main__":
    main()
